const greeHintMessages: Record<Language, string> = {
  sv: "Datorn och Gree-enheten måste vara på samma lokala nätverk. Sökningen använder UDP-port 7000; första anslutningen parar enheten.", en: "Your computer and Gree unit must be on the same local network. Discovery uses UDP port 7000; the first connection pairs the unit.", de: "Computer und Gree-Gerät müssen sich im selben lokalen Netzwerk befinden. Die Suche nutzt UDP-Port 7000; beim ersten Verbinden wird das Gerät gekoppelt.", fr: "L’ordinateur et l’appareil Gree doivent être sur le même réseau local. La recherche utilise le port UDP 7000 ; la première connexion associe l’appareil.", es: "El ordenador y el equipo Gree deben estar en la misma red local. La búsqueda usa el puerto UDP 7000; la primera conexión vincula el equipo.", it: "Il computer e l’unità Gree devono essere sulla stessa rete locale. La ricerca usa la porta UDP 7000; la prima connessione associa l’unità.", pt: "O computador e o aparelho Gree têm de estar na mesma rede local. A deteção usa a porta UDP 7000; a primeira ligação emparelha o aparelho.", nl: "Je computer en Gree-apparaat moeten op hetzelfde lokale netwerk zitten. Detectie gebruikt UDP-poort 7000; bij de eerste verbinding wordt het apparaat gekoppeld.", da: "Computeren og Gree-enheden skal være på samme lokale netværk. Søgning bruger UDP-port 7000; første forbindelse parrer enheden.", nb: "Datamaskinen og Gree-enheten må være på samme lokalnett. Søk bruker UDP-port 7000; første tilkobling parer enheten.", fi: "Tietokoneen ja Gree-laitteen on oltava samassa lähiverkossa. Haku käyttää UDP-porttia 7000; ensimmäinen yhteys muodostaa laiteparin.", pl: "Komputer i urządzenie Gree muszą być w tej samej sieci lokalnej. Wyszukiwanie używa portu UDP 7000; pierwsze połączenie paruje urządzenie.", cs: "Počítač a jednotka Gree musí být ve stejné místní síti. Vyhledávání používá port UDP 7000; první připojení zařízení spáruje.", sk: "Počítač a jednotka Gree musia byť v rovnakej lokálnej sieti. Vyhľadávanie používa port UDP 7000; prvé pripojenie jednotku spáruje.", hu: "A számítógépnek és a Gree készüléknek ugyanazon a helyi hálózaton kell lennie. A keresés a 7000-es UDP-portot használja; az első csatlakozás párosítja a készüléket.", ro: "Computerul și unitatea Gree trebuie să fie în aceeași rețea locală. Descoperirea folosește portul UDP 7000; prima conectare asociază unitatea.", el: "Ο υπολογιστής και η μονάδα Gree πρέπει να βρίσκονται στο ίδιο τοπικό δίκτυο. Η αναζήτηση χρησιμοποιεί τη θύρα UDP 7000· η πρώτη σύνδεση πραγματοποιεί σύζευξη.", tr: "Bilgisayarınız ve Gree ünitesi aynı yerel ağda olmalıdır. Keşif UDP 7000 bağlantı noktasını kullanır; ilk bağlantı üniteyi eşleştirir.", ja: "パソコンと Gree 機器を同じローカルネットワークに接続してください。検出には UDP ポート 7000 を使い、初回接続時に機器をペアリングします。", zh: "电脑和 Gree 设备必须连接到同一局域网。发现功能使用 UDP 7000 端口；首次连接时会配对设备。"
};
