const expectedCopyLength = keys.length - 3;
for (const language of languages) {
  if (copy[language].length !== expectedCopyLength) {
    throw new Error(`Translation count mismatch for ${language}: expected ${expectedCopyLength}, found ${copy[language].length}`);
  }
}

export const messages: Record<Language, Messages> = Object.fromEntries(languages.map((lang) => [lang, Object.fromEntries([
  ...keys.slice(0, -3).map((key, index) => [key, copy[lang][index]] as const),
  ["deviceLimit", deviceLimitMessages[lang]], ["daikinHint", daikinHintMessages[lang]], ["mitsubishiLocalHint", mitsubishiLocalHintMessages[lang]],
  ["greeHint", greeHintMessages[lang]], ["mideaScanHint", mideaScanHintMessages[lang]], ["lgTokenLabel", lgTokenLabelMessages[lang]],
  ["panasonicHint", panasonicHintMessages[lang]], ["samsungHint", samsungHintMessages[lang]], ["verificationCode", verificationCodeMessages[lang]],
  ["accountCountry", accountCountryMessages[lang]], ["greeCloudRegion", greeCloudRegionMessages[lang]], ["lgHint", lgHintMessages[lang]],
  ["add", extras[lang][0]], ["localBrand", extras[lang][1]], ["cloudBrand", extras[lang][2]],
  ["removeDevice", removeDeviceMessages[lang]], ["confirmRemoveDevice", confirmRemoveDeviceMessages[lang]], ["removedDevice", removedDeviceMessages[lang]],
  ["offline", connectionStatusMessages[lang].offline], ["checking", connectionStatusMessages[lang].checking],
  ["version", aboutMessages[lang][0]], ["author", aboutMessages[lang][1]], ["projectLicense", aboutMessages[lang][2]],
  ["thirdPartyLicenses", aboutMessages[lang][3]], ["readProjectLicense", aboutMessages[lang][4]], ["aboutLoadFailed", aboutMessages[lang][5]],
  ["verticalAirflow", airflowMessages[lang][0]], ["horizontalAirflow", airflowMessages[lang][1]], ["swing", airflowMessages[lang][2]],
])])) as Record<Language, Messages>;
export function detectLanguage(): Language {
  const saved = localStorage.getItem("klimat-language");
  if (saved && languages.includes(saved as Language)) return saved as Language;
  const candidate = navigator.language.toLowerCase().split(/[-_]/)[0];
  return languages.includes(candidate as Language) ? candidate as Language : "en";
}
